def is_nested(string):
    """
    Return True if the string contains a valid subsequence of brackets
    where at least one bracket is nested, i.e., the subsequence "[[]]" exists.
    """
    # Find first '['
    i = 0
    while i < len(string) and string[i] != '[':
        i += 1
    if i == len(string):
        return False

    # Find second '['
    i += 1
    while i < len(string) and string[i] != '[':
        i += 1
    if i == len(string):
        return False

    # Find first ']'
    i += 1
    while i < len(string) and string[i] != ']':
        i += 1
    if i == len(string):
        return False

    # Find second ']'
    i += 1
    while i < len(string) and string[i] != ']':
        i += 1
    return i < len(string)
