def word_count(text):
    counts = {}
    for w in text.split():
        # Remove leading/trailing punctuation
        w = w.strip('.,!?:;')
        if not w:
            continue
        # Case-insensitive counting
        w = w.lower()
        counts[w] = counts.get(w, 0) + 1
    return counts
